import{_ as t,J as s,b as n,e as i,a8 as r,f as o,L as l}from"./chunks/framework.C-MVLAPI.js";const C=JSON.parse('{"title":"TCanvas32","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Paths","entity":"TCanvas32","kind":"Class","declaration":"TCanvas32 = class(TCustomCanvas)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TCustomPath","TFlattenedPath","TCustomCanvas","TCanvas32"],"summary":"High-level 2D vector canvas rendering engine bound to a TBitmap32 target, managing brushes, text rendering, and polygon rasterization.","title":"TCanvas32","date":1788637341000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Paths/TCanvas32/index.md","filePath":"api/GR32_Paths/Classes/TCanvas32/index.md","lastUpdated":1788637341000,"timestamp":1788637341000,"datetime":"2026-09-05T19:42:21.000Z","contributors":[]}'),d={name:"api/GR32_Paths/TCanvas32/index.md"};function p(c,a,h,T,u,m){const e=s("ApiMembers");return n(),i("div",null,[a[0]||(a[0]=r('<h2 id="declaration" tabindex="-1">Declaration <a class="header-anchor" href="#declaration" aria-label="Permalink to &quot;Declaration&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TCanvas32 = </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(TCustomCanvas)</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCanvas32</code> is the primary 2D vector drawing canvas in Graphics32. It binds path construction directives inherited from <a href="/api/GR32_Paths/TCustomPath/">TCustomPath</a> and <a href="/api/GR32_Paths/TFlattenedPath/">TFlattenedPath</a> directly to a target <a href="/api/GR32/TBitmap32/">TBitmap32</a> surface.</p><p>Key capabilities of <code>TCanvas32</code> include:</p><ul><li><strong>Bitmap Drawing Target</strong>: Operates directly on an assigned <a href="/api/GR32_Paths/TCanvas32/Bitmap">Bitmap</a> instance (<a href="/api/GR32/TBitmap32/">TBitmap32</a>).</li><li><strong>Brush Collection Pipeline</strong>: Manages a collection of vector stroke and fill brushes in <a href="/api/GR32_Paths/TCanvas32/Brushes">Brushes</a> (<a href="/api/GR32_Brushes/TBrushCollection/">TBrushCollection</a>), applying solid colors, strokes, dashes, or custom pattern fillers during path rendering.</li><li><strong>Configurable Polygon Renderer</strong>: Uses an anti-aliased software polygon renderer (<a href="/api/GR32_Paths/TCanvas32/Renderer">Renderer</a>, <a href="/api/GR32_Paths/TCanvas32/RendererClassName">RendererClassName</a>) such as <code>TPolygonRenderer32VPR</code> or <code>TPolygonRenderer32LCD</code> to rasterize paths.</li><li><strong>Vector Text Outline Rendering</strong>: Converts TrueType/OpenType font outlines into vector path geometry via <a href="/api/GR32_Paths/TCanvas32/RenderText">RenderText</a> and measures text layout bounds via <a href="/api/GR32_Paths/TCanvas32/MeasureText">MeasureText</a>.</li></ul>',6)),o("p",null,[l(e,{type:"members"})])])}const v=t(d,[["render",p]]);export{C as __pageData,v as default};
